/* ---------------------------------------------------------
   data.js — 資料載入與查詢層
   ---------------------------------------------------------
   負責：
     1. fetch() 載入 data/ 目錄下的 JSON（圖層目錄、來源設定、
        地理範圍、縣市→來源對應、歷史地名比對規則）
     2. 把 JSON 轉成其他模組慣用的記憶體內資料形狀
        （layer.year / layer.fmt 對應來源檔案的
        layer.dateLabel / layer.format）
     3. 提供 resolveTileUrl()，取代原本寫死在各個 XXX_TILE()
        函式裡的網址組成規則；每個來源的 tile URL 樣板放在該來源
        自己的 data/layers/<id>.json 裡的 provider 欄位。
     4. 提供跟「資料查詢」有關的共用函式：依 key 找圖層來源、
        依地址縣市／鄉鎮比對可用的圖資來源、地名文字比對。

   資料檔案配置：
     data/layers/index.json     開發用來源清單（id/file/name/layerCount）
     data/layers/<id>.json      開發用：單一來源的圖層目錄 + provider
                                  （tile URL 樣板）+ region（bbox），
                                  方便編輯、方便看 git diff
     data/layers.bundle.json    實際部署時瀏覽器載入的合併檔（由
                                  tools/build-layers-bundle.js 產生），
                                  一次 fetch 取代 19 次，避免請求數過多
                                  拖慢初始載入
     data/source-map.json       縣市→來源的對應規則（跨來源查詢邏輯，
                                  不屬於任何單一來源，所以獨立）
     data/historical-names.json 地名詞尾與未來的新舊地名對照表

   新增一張歷史地圖時：
     1. 新增一個 data/layers/<新id>.json（圖層目錄 + provider + region）
     2. 在 data/layers/index.json 加一筆 { id, file, name, layerCount }
     3. 執行 `node tools/build-layers-bundle.js` 重新產生
        data/layers.bundle.json（部署前一定要做這一步，否則瀏覽器
        載入的還是舊資料）
     4. 視情況在 data/source-map.json 加一筆縣市對應規則
   不需要更動任何既有來源的檔案，也不需要更動任何 .js 檔案。
--------------------------------------------------------- */
// data.js 本來完全沒有 import——這是唯一一個例外：core/tileLoadGuard.js
// 只依賴 core/tileGeo.js（純函式、零依賴），三者形成單向、不回頭的
// 依賴鏈，不會像 store.js／features/ 底下的 feature 層模組那樣有反過來
// import data.js 的循環風險，所以不需要比照 setCustomSourcesProvider()
// 那套依賴注入，直接 import 即可。
import { createGuardedTileLoadFunction, DEFAULT_TILE_CACHE_SIZE } from './core/tileLoadGuard.js';

// 用單一 const 物件裝載這 5 個「載入完成後才有值」的模組狀態，取代原本
// 個別 export let 逐一重新賦值的寫法（SonarQube javascript:S6861：不要
// export 可變的 let binding）。loadAppData() 內仍會整批重新賦值這些屬性，
// 但外部模組拿到的是同一個物件參照，改成讀 DATA.LAYER_SOURCES 等屬性。
export const DATA = {
  LAYER_SOURCES: [],
  REGION_EXTENTS: {},
  SOURCE_MAP_RULES: null,
  HISTORICAL_NAMES: null,
  PLACE_NAME_SUFFIXES: [],
};

// 使用者自訂 WMTS／XYZ 圖層（`custom:<id>` key 命名空間）不屬於
// LAYER_SOURCES——那批是 data/layers/*.json 產生的內建 curated 資料。
// data.js 刻意不直接 import store.js／features/ 底下的 feature 層模組
// （避免 store.js／features/multiOverlay.js 反過來 import data.js 時
// 形成循環依賴），改用參數注入：由 features/multiOverlay.js 在初始化時
// 呼叫 setCustomSourcesProvider() 把「怎麼拿到目前的自訂來源清單」這件事
// 註冊進來，makeSourceForKey()／titleForKey() 需要時再透過這個函式
// 去查，兩邊模組互不 import 對方。
let customSourcesProvider = () => [];
export function setCustomSourcesProvider(fn){
  customSourcesProvider = typeof fn === 'function' ? fn : (() => []);
}

const SAT_URL = 'https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}';

// 來源 id → 所屬國家／地區分組（'tw' 台灣／'cn' 中國／'other' 其他），
// 純粹用來讓側邊欄能依國家分組篩選、縮短捲動範圍，不影響任何資料載入
// 或圖層邏輯。新增來源時記得在這裡補一筆；沒列到的 id 一律歸類到
// 'other'（未來加入台灣、中國以外的來源時，不用先改這裡也能正常顯示，
// 只是會先出現在「其他」分類）。
const SOURCE_COUNTRY = {
  sinica: 'tw', keelung: 'tw', taipei: 'tw', udd: 'tw', newtaipei: 'tw',
  taoyuan: 'tw', hsinchu: 'tw', thm: 'tw', taichung: 'tw', changhua: 'tw',
  lukang: 'tw', chiayi: 'tw', tainan: 'tw', kaohsiung: 'tw', pingtung: 'tw',
  hakkaliudui: 'tw', yilan: 'tw', hualien: 'tw', kinmen: 'tw',
  beijing: 'cn', tianjin: 'cn', shanghai: 'cn', nanjing: 'cn', hangzhou: 'cn',
  wuhan: 'cn', guangzhou: 'cn', kunming: 'cn', suzhou: 'cn', hongkong: 'cn',
  ccts: 'cn', nlsc: 'tw',
  tamsui: 'tw', puli: 'tw', penghu: 'tw', taitung: 'tw'
};
function countryForSourceId(id){
  return SOURCE_COUNTRY[id] || 'other';
}

// udd 來源比較特殊：每個圖層的 tile 網址不是套同一個樣板算出來的，
// 而是分成 ArcGIS WMTS REST 版 / 舊版 UDDWMTS 版兩種，組出來的完整網址
// 直接存在該來源檔案裡每筆圖層的 url 欄位。resolveTileUrl() 依
// 來源檔案 provider 欄位裡的 literalUrl 旗標，決定要套樣板還是直接取 layer.url。
function resolveTileUrl(provider, layer){
  if(!provider) return '';
  if(provider.literalUrl) return layer.url || '';
  return (provider.tileTemplate || '')
    .replace('{id}', layer.id)
    .replace('{format}', layer.fmt);
}

/* ---------------------------------------------------------
   將每個分類內的圖層依年代排序（由舊到新）
   年份格式不一（純西元年、"1930s"、"清"、"日治"、"戰後"等），
   用 yearSortValue 統一轉成可比較的數字後再排序。
--------------------------------------------------------- */
function yearSortValue(y){
  const s = String(y);
  const m = /\d{3,4}/.exec(s); // 抓出字串中第一組 3~4 位數字（例：1930s → 1930）
  if(m) return Number.parseInt(m[0], 10);
  if(s === '清') return 1850;    // 清代，無精確年份者排在最前
  if(s === '日治') return 1910;  // 日治時期通用標籤，概略排在日治中期
  if(s === '戰後') return 1950;  // 戰後通用標籤，概略排在戰後初期
  return 9999;                    // 年代不明（如「—」）排在該分類最後
}

function sortAllLayers(){
  DATA.LAYER_SOURCES.forEach(src=>{
    src.categories.forEach(cat=>{
      if(cat.groups){
        cat.groups.forEach(g=> g.layers.sort((a,b)=> yearSortValue(a.year) - yearSortValue(b.year)));
      } else {
        cat.layers.sort((a,b)=> yearSortValue(a.year) - yearSortValue(b.year));
      }
    });
  });
}

/* ---------------------------------------------------------
   最基本的 JSON metadata 型別檢查（非完整 schema library，只檢查
   後續程式碼會直接假設存在、且會被拿去 .map()／.forEach()／存取
   巢狀欄位的關鍵結構），目的是讓格式錯誤在載入當下就丟出清楚的
   錯誤訊息（例如「layers.bundle.json：sources[3] 缺少 provider」），
   而不是等到執行到 sortAllLayers()／matchSourceIdsForAddress() 等
   更深層的地方才丟出難以定位問題的例外。
   驗證失敗時直接 throw，交由呼叫端（main.js 的 try/catch）統一
   顯示「圖層資料載入失敗」提示，不個別 catch。
--------------------------------------------------------- */
function assertShape(cond, message){
  if(!cond) throw new Error(`[資料格式錯誤] ${message}`);
}

function validateLayersBundle(layersData){
  assertShape(layersData && typeof layersData === 'object', 'layers.bundle.json 不是有效的物件');
  assertShape(Array.isArray(layersData.sources), 'layers.bundle.json 缺少 sources 陣列');
  layersData.sources.forEach((src, i) => {
    const tag = `layers.bundle.json：sources[${i}]`;
    assertShape(src && typeof src === 'object', `${tag} 不是有效的物件`);
    assertShape(typeof src.id === 'string' && src.id, `${tag} 缺少 id`);
    assertShape(typeof src.name === 'string' && src.name, `${tag}（id=${src.id}） 缺少 name`);
    assertShape(src.provider && typeof src.provider === 'object', `${tag}（id=${src.id}） 缺少 provider`);
    assertShape(src.region && Array.isArray(src.region.bbox) && src.region.bbox.length === 4,
      `${tag}（id=${src.id}） 缺少合法的 region.bbox（需為 [minLon,minLat,maxLon,maxLat]）`);
    assertShape(Array.isArray(src.categories), `${tag}（id=${src.id}） 缺少 categories 陣列`);
    src.categories.forEach((cat, ci) => {
      const ctag = `${tag}（id=${src.id}）categories[${ci}]`;
      assertShape(cat && typeof cat.name === 'string', `${ctag} 缺少 name`);
      assertShape(Array.isArray(cat.layers) || Array.isArray(cat.groups),
        `${ctag} 需要有 layers 或 groups 其中一個陣列`);
      const layerLists = cat.groups
        ? cat.groups.map(g => g.layers)
        : [cat.layers];
      layerLists.forEach((layers, gi) => {
        const groupSuffix = cat.groups ? ` groups[${gi}]` : '';
        assertShape(Array.isArray(layers), `${ctag}${groupSuffix} 缺少 layers 陣列`);
        layers.forEach((l, li) => {
          const ltag = `${ctag} layers[${li}]`;
          assertShape(typeof l.id === 'string' && l.id, `${ltag} 缺少 id`);
          assertShape(typeof l.title === 'string', `${ltag}（id=${l.id}） 缺少 title`);
          assertShape(typeof l.format === 'string', `${ltag}（id=${l.id}） 缺少 format`);
        });
      });
    });
  });
}

function validateSourceMap(sourceMapData){
  assertShape(sourceMapData && typeof sourceMapData === 'object', 'source-map.json 不是有效的物件');
  assertShape(Array.isArray(sourceMapData.alwaysInclude), 'source-map.json 缺少 alwaysInclude 陣列');
  assertShape(Array.isArray(sourceMapData.rules), 'source-map.json 缺少 rules 陣列');
  sourceMapData.rules.forEach((rule, i) => {
    const tag = `source-map.json：rules[${i}]`;
    assertShape(Array.isArray(rule.includes), `${tag} 缺少 includes 陣列`);
    assertShape(Array.isArray(rule.sources), `${tag} 缺少 sources 陣列`);
  });
  // alwaysIncludeUnless 是選填欄位（沒有就當空陣列處理）：跟 alwaysInclude 一樣一律列入候選，
  // 但只在地址「沒有」命中 excludeIfIncludes 任何關鍵字時才生效——用來處理像 ccts（涵蓋全中國、
  // 不屬於任何單一縣市）這種「非台灣地址才觸發」的來源，排除清單比對邏輯跟 rules 一致，
  // 只是命中後是「不要加入」而不是「加入」。
  if(sourceMapData.alwaysIncludeUnless !== undefined){
    assertShape(Array.isArray(sourceMapData.alwaysIncludeUnless), 'source-map.json 的 alwaysIncludeUnless 必須是陣列');
    sourceMapData.alwaysIncludeUnless.forEach((rule, i) => {
      const tag = `source-map.json：alwaysIncludeUnless[${i}]`;
      assertShape(Array.isArray(rule.sources), `${tag} 缺少 sources 陣列`);
      assertShape(Array.isArray(rule.excludeIfIncludes), `${tag} 缺少 excludeIfIncludes 陣列`);
    });
  }
}

function validateHistoricalNames(namesData){
  assertShape(namesData && typeof namesData === 'object', 'historical-names.json 不是有效的物件');
  assertShape(Array.isArray(namesData.suffixes), 'historical-names.json 缺少 suffixes 陣列');
  assertShape(namesData.aliases && typeof namesData.aliases === 'object', 'historical-names.json 缺少 aliases 物件');
}

export async function loadAppData(){
  const [layersData, sourceMapData, namesData] = await Promise.all([
    fetch('./data/layers.bundle.json').then(r => r.json()),
    fetch('./data/source-map.json').then(r => r.json()),
    fetch('./data/historical-names.json').then(r => r.json())
  ]);

  validateLayersBundle(layersData);
  validateSourceMap(sourceMapData);
  validateHistoricalNames(namesData);

  const sourceFiles = layersData.sources;

  DATA.SOURCE_MAP_RULES = sourceMapData;
  DATA.HISTORICAL_NAMES = namesData;
  DATA.PLACE_NAME_SUFFIXES = namesData.suffixes;

  // 每個來源檔案自帶 provider（tile URL 樣板／literalUrl 旗標）與
  // region（bbox），不用再另外查表比對 id，直接就地取用。
  DATA.REGION_EXTENTS = {};
  sourceFiles.forEach(src => { DATA.REGION_EXTENTS[src.id] = src.region.bbox; });

  // src.json -> LAYER_SOURCES
  // （沿用原本 { id, name, tileUrl, attribution, categories:[{category, layers|groups}] } 形狀，
  //   layer.fmt / layer.year 對應回來源檔案的 layer.format / layer.dateLabel，
  //   讓其他模組沒有變動過的渲染、搜尋、比對程式碼可以直接使用。）
  DATA.LAYER_SOURCES = sourceFiles.map(src => {
    const provider = src.provider;
    const mapLayer = (l) => ({
      id: l.id,
      title: l.title,
      fmt: l.format,
      year: l.dateLabel,   // 顯示用字串（沿用舊欄位名），不變
      yearNum: l.year,     // 數字或 null，時間軸定位／排序用
      scale: l.scale,      // 比例尺字串（例如 "1:25000"）或 null，未來篩選用（新增）
      type: l.type,        // 圖層類型（地形圖／地籍圖／行政區劃圖…）或 null，搜尋結果類型篩選用
      keywords: l.keywords || [], // 關鍵字陣列，未提供時給空陣列
      url: l.url, // 只有 udd 圖層會用到（file-exists 樣板來源沒有這個欄位）
      region: l.region || null, // 圖層自身的 WGS84 bbox（選填），供空間索引篩選用，沒有時 fallback 為 null
      legend: l.legend || null, // 圖例頁面 URL（選填），沒有時 fallback 為 null，UI 端用來決定要不要顯示圖例按鈕
    });
    const categories = src.categories.map(cat => {
      if(cat.groups){
        return {
          category: cat.name,
          groups: cat.groups.map(g => ({ name: g.name, layers: g.layers.map(mapLayer) }))
        };
      }
      return { category: cat.name, layers: cat.layers.map(mapLayer) };
    });
    return {
      id: src.id,
      name: src.name,
      country: countryForSourceId(src.id), // 'tw' | 'cn' | 'other'，供側邊欄國家篩選按鈕使用
      tileUrl: (layer) => resolveTileUrl(provider, layer),
      attribution: src.attribution,
      categories
    };
  });

  sortAllLayers();
}

/* ---------------------------------------------------------
   共用：依 key 建立圖層來源
   key 格式："base:osm" / "base:sat" / "hist:<id>:<fmt>"
--------------------------------------------------------- */
export function findLayerById(src, id){
  for(const cat of src.categories){
    if(cat.groups){
      for(const g of cat.groups){
        const l = g.layers.find(x => x.id === id);
        if(l) return l;
      }
    } else {
      const l = cat.layers.find(x => x.id === id);
      if(l) return l;
    }
  }
  return null;
}

// 把「從 GetCapabilities 解析出來、已經被 features/wmtsImport.js 抽成
// 純資料格式」的 WMTS 圖層設定，重建成真正的 ol.source.WMTS。刻意不在
// 這裡重新 fetch/parse GetCapabilities——那件事只在使用者「匯入」的
// 當下做一次，抽出來的 tileGrid 參數（resolutions／matrixIds／origin…）
// 全部是可以存進 localStorage 的純資料，往後每次建立圖層都直接拿這份
// 資料組 ol.tilegrid.WMTS + ol.source.WMTS，不需要也不依賴該服務的
// GetCapabilities 端點之後還連得到、還能再抓一次。
//
// 不設定 crossOrigin：使用者自訂的服務不保證有開放 CORS（GetCapabilities
// 能不能讀跟圖磚圖片能不能讀是兩件事，見 makeSourceForKey() 的說明），
// 圖磚本身用一般（非 crossorigin）的 <img> 請求載入即可正常顯示，只有
// 「畫面截圖」（drawTool.js 的 exportImage()）這種要用 JS 讀出 canvas
// 像素資料的操作，才會因為瀏覽器的安全限制而失敗——那支函式本來就有
// 包 try/catch 顯示對應的錯誤訊息，不會整個當掉。
function makeWmtsSourceFromEntry(entry){
  const w = entry.wmts;
  if(!w || !Array.isArray(w.resolutions) || !Array.isArray(w.matrixIds)){
    console.warn('自訂 WMTS 圖層缺少必要的 tileGrid 資料，無法建立', entry);
    return new ol.source.XYZ({ url: '' });
  }
  try{
    const tileGrid = new ol.tilegrid.WMTS({
      origin: w.origin,
      resolutions: w.resolutions,
      matrixIds: w.matrixIds,
      tileSize: w.tileSize || 256,
      extent: w.extent || undefined
    });
    return new ol.source.WMTS({
      urls: w.urls,
      layer: w.layer,
      matrixSet: w.matrixSet,
      format: w.format,
      projection: w.projection || 'EPSG:3857',
      requestEncoding: w.requestEncoding,
      style: w.style,
      tileGrid,
      attributions: entry.attribution || '',
      // 使用者自訂服務沒有可靠的 WGS84 bbox 資料來源，不傳 regionBbox——
      // createGuardedTileLoadFunction() 內建的防呆會自動略過邊界檢查，
      // 只保留逾時保護（見 core/tileLoadGuard.js）。
      tileLoadFunction: createGuardedTileLoadFunction({}),
      // 不帶這個選項 OL 會當成 0（不是退回預設 2048），LRU 過期機制
      // 形同虛設——見 DEFAULT_TILE_CACHE_SIZE 的說明。
      cacheSize: DEFAULT_TILE_CACHE_SIZE
    });
  }catch(err){
    console.warn('建立自訂 WMTS 圖層失敗（資料可能已經跟服務端改版不相容）', entry, err);
    return new ol.source.XYZ({ url: '' });
  }
}

export function makeSourceForKey(key){
  if(key === 'base:osm') return new ol.source.OSM({ crossOrigin: 'anonymous', cacheSize: DEFAULT_TILE_CACHE_SIZE });
  if(key === 'base:sat') return new ol.source.XYZ({ url: SAT_URL, attributions: 'Esri, Maxar, Earthstar Geographics', crossOrigin: 'anonymous', cacheSize: DEFAULT_TILE_CACHE_SIZE });
  if(key.startsWith('custom:')){
    const id = key.slice('custom:'.length);
    const entry = customSourcesProvider().find(s => s.id === id);
    if(!entry) return new ol.source.XYZ({ url: '' });
    // 兩種自訂來源：
    //   'wmts' —— 從 GetCapabilities 匯入的正牌 WMTS 圖層（見上面
    //             makeWmtsSourceFromEntry()，可以是任何 TileMatrixSet）。
    //   'xyz'（預設，含舊資料）—— 使用者手動貼的網址樣板，只認直接帶
    //             {z}/{x}/{y} 的 XYZ 金字塔（含剛好是 EPSG:3857 的
    //             WMTS KVP 網址）。
    // 兩者都刻意不設定 crossOrigin，理由見上面 makeWmtsSourceFromEntry()
    // 的註解：這樣即使該服務沒開放 CORS，圖磚一樣能正常顯示，只有
    // 「截圖匯出」這個要讀 canvas 像素的操作在那個當下會失敗（已有
    // 對應的錯誤訊息與 try/catch，不影響一般瀏覽）。
    if(entry.type === 'wmts') return makeWmtsSourceFromEntry(entry);
    return new ol.source.XYZ({
      url: entry.urlTemplate,
      attributions: entry.attribution || '',
      tileLoadFunction: createGuardedTileLoadFunction({}), // 同上，沒有可靠 bbox，只做逾時保護
      cacheSize: DEFAULT_TILE_CACHE_SIZE
    });
  }
  const parts = key.split(':'); // ["hist", sourceId, id, fmt]
  const src = DATA.LAYER_SOURCES.find(s => s.id === parts[1]);
  if(!src) return new ol.source.XYZ({ url: '', crossOrigin: 'anonymous' });
  const layer = findLayerById(src, parts[2]);
  if(!layer) return new ol.source.XYZ({ url: '', crossOrigin: 'anonymous' });
  // 邊界保護用的 bbox：優先用圖層自己的 region.bbox（較精確，但非強制
  // 存在），沒有時退回來源層級的 REGION_EXTENTS（較粗略，但
  // validateLayersBundle() 保證每個來源都有，見 loadAppData()）。兩層
  // 都沒有合法值時，bboxIntersects() 內建防呆會自動不排除，安全。
  const regionBbox = layer.region?.bbox || DATA.REGION_EXTENTS[src.id];
  return new ol.source.XYZ({
    url: src.tileUrl(layer),
    attributions: src.attribution,
    crossOrigin: 'anonymous',
    tileLoadFunction: createGuardedTileLoadFunction({ regionBbox }),
    cacheSize: DEFAULT_TILE_CACHE_SIZE
  });
}

export function titleForKey(key){
  if(key === 'base:osm') return '現代地圖';
  if(key === 'base:sat') return '衛星影像';
  if(key.startsWith('custom:')){
    const id = key.slice('custom:'.length);
    const entry = customSourcesProvider().find(s => s.id === id);
    return entry ? entry.name : key;
  }
  const parts = key.split(':');
  const src = DATA.LAYER_SOURCES.find(s => s.id === parts[1]);
  if(!src) return key;
  for(const cat of src.categories){
    const layersArr = cat.groups ? cat.groups.flatMap(g=>g.layers) : cat.layers;
    for(const l of layersArr){
      if(l.id === parts[2]) return `${l.year} ${l.title}`;
    }
  }
  return key;
}

// 把 { src, layer } 組成 store 用的可序列化 key 字串（"hist:sourceId:id:fmt"）。
export function layerKey(src, layer){
  return `hist:${src.id}:${layer.id}:${layer.fmt}`;
}

// layerKey() 的反向操作：把 key 字串解析回 { src, layer }。
// 傳入底圖 key（"base:osm"/"base:sat"）或找不到對應圖層時回傳 null，
// 呼叫端看到 null 就知道這個 key 不是歷史圖層（是底圖，或已經失效）。
export function resolveOverlayKey(key){
  if(!key || key === 'base:osm' || key === 'base:sat') return null;
  const parts = key.split(':'); // ["hist", sourceId, id, fmt]
  const src = DATA.LAYER_SOURCES.find(s => s.id === parts[1]);
  if(!src) return null;
  const layer = findLayerById(src, parts[2]);
  if(!layer) return null;
  return { src, layer };
}

/* ---------------------------------------------------------
   依 Nominatim 回傳的地址元件，比對出地理範圍相關的圖資來源 id。
   規則資料放在 data/source-map.json（SOURCE_MAP_RULES），這裡只是
   通用的規則解讀器：不再用一長串 if(county.includes(...)) 寫死縣市
   對應，新增/調整縣市對應時改 JSON 就好，不需要動這支函式。

   不特別區分「縣市」跟「鄉鎮」兩層分開比對，而是把地址所有可能相關
   的欄位合併成一個字串一起比對。原因：Nominatim 對台灣「區」這種
   直轄市行政區劃，實際塞進哪個欄位並不穩定（例如「八德區」這種區級
   資訊，實測過有時候會出現在 city 欄位——但 city 同時也是判斷縣市
   常用的欄位之一），同一個欄位名稱在不同查詢代表的行政層級可能不同，
   硬性規定「這個欄位一定是縣市、那個欄位一定是鄉鎮」並不可靠。
   合併後統一比對，不管值落在哪個欄位、對應到哪一層，只要字串裡有
   符合的關鍵字就抓得到，跟極端狀況下漏掉整個來源比起來，多檢查
   幾個不相關的來源是可以接受的代價（後面还有座標 bbox 與圖磚探測
   把關，不會因此顯示出錯誤的圖層）。
--------------------------------------------------------- */
const ADDRESS_MATCH_FIELDS = [
  'county', 'state', 'region',                                    // 縣市／省層級
  'city', 'city_district', 'district', 'municipality', 'township', // 直轄市／區／鄉鎮層級
  'town', 'suburb', 'quarter', 'borough', 'village', 'hamlet', 'neighbourhood' // 鄉鎮市區／村里層級
];

export function matchSourceIdsForAddress(addr){
  addr = addr || {};
  const haystack = ADDRESS_MATCH_FIELDS.map(k => addr[k] || '').join('');
  const ids = new Set(DATA.SOURCE_MAP_RULES.alwaysInclude); // 全臺涵蓋來源，一律列入候選

  // alwaysIncludeUnless：跟 alwaysInclude 一樣預設列入候選，但只要地址命中
  // excludeIfIncludes 裡任何一個關鍵字（例如台灣的縣市名稱），就不加入。
  // 用來處理「涵蓋全中國、非台灣地址才觸發」這種來源（見 source-map.json 裡的說明）。
  (DATA.SOURCE_MAP_RULES.alwaysIncludeUnless || []).forEach(rule => {
    const excluded = rule.excludeIfIncludes.some(k => haystack.includes(k));
    if(!excluded) rule.sources.forEach(id => ids.add(id));
  });

  DATA.SOURCE_MAP_RULES.rules.forEach(rule => {
    const hit = rule.includes.some(k => haystack.includes(k));
    if(!hit) return;
    rule.sources.forEach(id => ids.add(id));

    if(rule.districtRule){
      const dr = rule.districtRule;
      const districtList = dr.includes || DATA.SOURCE_MAP_RULES.districtSets[dr.includesFromSet] || [];
      if(districtList.some(d => haystack.includes(d))){
        dr.sources.forEach(id => ids.add(id));
      }
    }
  });

  return Array.from(ids);
}

/* ---------------------------------------------------------
   文字比對候選圖層

   用途：像 thm（桃竹苗舊地籍圖）這種單一來源底下就有數百筆「堡→庄」圖層
   的資料，只靠 matchSourceIdsForAddress() 篩到「來源」還不夠，這裡再用
   Nominatim 回傳的鄉鎮／村里等地址元件，跟每個來源「內部」的圖層標題做
   純文字子字串比對，先篩出候選、減少要發送 file-exists 圖磚請求的筆數。

   注意：這不是地理邊界判斷（沒有用到任何向量圖資或座標運算），單純比對
   文字是否相符，新舊地名對不上時可能篩不出東西，因此一定要保留「完全沒
   命中就退回全部檢查」這個備援，避免因為文字比對誤判而漏掉真正有資料的
   圖層。
--------------------------------------------------------- */

// 常見的行政區／地籍圖名稱詞尾。比對前把這些詞尾去掉，取地名的核心字，
// 讓「新埔鎮」（現代行政區）跟「新埔街」（日治地籍圖標題）能對得上。
// 詞尾清單放在 data/historical-names.json 的 suffixes 欄位（PLACE_NAME_SUFFIXES）。
function stripPlaceNameSuffix(name){
  let s = (name || '').trim();
  // 只在還剩至少 2 個字的情況下才繼續去尾，避免把兩個字的地名（例如「五股」）
  // 誤砍到只剩 1 個字，變成比對什麼都會命中的無意義關鍵字。
  while(s.length > 2 && DATA.PLACE_NAME_SUFFIXES.includes(s[s.length - 1])){
    s = s.slice(0, -1);
  }
  return s;
}

// 只掃「鄉鎮市區、村里、鄰」這個層級的欄位，不掃「縣市」層級
//（county/state/region 這類）。原因：地籍圖標題裡的舊地名通常是村里／
// 鄉鎮等級的地名（例如「塔仔脚庄」），縣市名稱（例如「臺南市」）常常
// 剛好跟該縣市自己的圖層標題有一兩個字重疊，若也拿來當關鍵字，會造成
// 大量「誤篩窄」——候選名單非空、但排除掉了真正該出現的圖層，而且因為
// 候選裡通常會有幾筆剛好真的有資料，兩階段備援的「已有命中就不擴大
// 檢查」機制不會啟動，導致真正有資料的圖層被永久排除在結果外。
//
// 這裡刻意列出多個可能的欄位名稱（而非只列 5 個），是因為 Nominatim
// 對台灣「區」這種行政區劃，實際塞進哪個欄位並不穩定（直轄市的區有時
// 出現在 city_district，有時出現在 city 或 district），與其只賭少數
// 幾個欄位名稱，不如把「鄉鎮市區」這個層級所有常見的欄位名稱都列進來；
// 但明確不包含 county/state/region 這種縣市／省層級的欄位。
const PLACE_ADDR_FIELDS = [
  'town', 'city', 'city_district', 'district', 'municipality',
  'township', 'suburb', 'quarter', 'borough',
  'village', 'hamlet', 'neighbourhood'
];

// 從 Nominatim 回傳的地址元件中，取出可能對應到舊地名（堡、庄、街）的
// 關鍵字候選：鄉鎮市區、村里、鄰里等欄位都納入，因為地籍圖標題的「庄」
// 有時對應現在的鄉鎮（例如「新埔街」對「新埔鎮」），有時對應到村里
// （例如較小的聚落）。同時保留「去尾前」與「去尾後」兩種寫法，增加比對到
// 的機會；只留 2 個字以上的關鍵字，避免單一個字大量誤中。
//
// 除了動態去尾之外，也查 historical-names.json 的 aliases 對照表：
// 如果去尾前或去尾後的名稱剛好是對照表裡登記過的現代地名（例如
// 「竹北市」「竹北」），就把對照表裡登記的舊地名（例如「竹北二堡」）
// 也一併加進關鍵字，讓比對能命中完全對不上字面、100 年前的地名。
// 對照表不用做到逐庄，做到「堡」這種較粗的層級即可：堡名本來就包含在
// 每一筆圖層標題裡（例如「新竹廳竹北二堡塔仔脚庄」），命中堡名關鍵字
// 就會篩出該堡底下全部圖層，範圍雖然比逐庄篩選寬一點，但後面還有圖磚
// 探測把關，不會因此篩出錯誤結果，只是候選數量比逐庄篩選略多而已。
export function extractPlaceKeywords(addr){
  addr = addr || {};
  const rawFields = PLACE_ADDR_FIELDS.map(key => addr[key]);
  const keywords = new Set();
  const aliases = DATA.HISTORICAL_NAMES?.aliases || {};
  rawFields.forEach(name=>{
    const trimmed = (name || '').trim();
    if(!trimmed) return;
    if(trimmed.length >= 2) keywords.add(trimmed);
    const stripped = stripPlaceNameSuffix(trimmed);
    if(stripped.length >= 2) keywords.add(stripped);

    // 對照表查詢：去尾前、去尾後的名稱都試著查一次
    [trimmed, stripped].forEach(name=>{
      const oldNames = aliases[name];
      if(oldNames) oldNames.forEach(old => keywords.add(old));
    });
  });
  return Array.from(keywords);
}

// 用地址關鍵字，從某個來源的候選圖層裡先篩出「標題包含關鍵字」的圖層。
// 找不到任何關鍵字，或關鍵字完全沒有命中任何標題時回傳 null，
// 呼叫端看到 null 就知道要退回「這個來源全部圖層都檢查」當備援。
export function prefilterLayersByPlaceName(sourceCandidates, keywords){
  if(!keywords || keywords.length === 0) return null;
  const matched = sourceCandidates.filter(c =>
    keywords.some(k => c.layer.title.includes(k))
  );
  return matched.length > 0 ? matched : null;
}
